## SwiftData - Modern Persistence

SwiftData is Apple's modern persistence framework (iOS 17+).

### Defining Models

```swift
import SwiftData

@Model
class Task {
    var title: String
    var taskDescription: String?
    var isCompleted: Bool
    var priority: Int
    var createdAt: Date

    @Relationship(deleteRule: .cascade)
    var subtasks: [Subtask]

    init(title: String, description: String? = nil, priority: Int = 0) {
        self.title = title
        self.taskDescription = description
        self.isCompleted = false
        self.priority = priority
        self.createdAt = Date()
        self.subtasks = []
    }
}

@Model
class Subtask {
    var title: String
    var isCompleted: Bool
    var task: Task?

    init(title: String) {
        self.title = title
        self.isCompleted = false
    }
}
```

### Setup

```swift
@main
struct MyApp: App {
    var body: some Scene {
        WindowGroup {
            ContentView()
        }
        .modelContainer(for: [Task.self, Subtask.self])
    }
}
```

### Querying Data

```swift
struct TaskListView: View {
    @Environment(\.modelContext) private var context
    @Query(sort: \Task.createdAt, order: .reverse) 
    private var tasks: [Task]

    var body: some View {
        List(tasks) { task in
            TaskRow(task: task)
                .swipeActions {
                    Button(role: .destructive) {
                        context.delete(task)
                    } label: {
                        Label("Delete", systemImage: "trash")
                    }
                }
        }
    }

    func addTask(title: String) {
        let task = Task(title: title)
        context.insert(task)
    }
}

// Filtered query
@Query(
    filter: #Predicate<Task> { !$0.isCompleted },
    sort: \Task.priority,
