private var pendingTasks: [Task]
```

## Core Data (Pre-iOS 17)

```swift
// NSManagedObject subclass
class CDTask: NSManagedObject {
    @NSManaged var title: String
    @NSManaged var isCompleted: Bool
    @NSManaged var createdAt: Date
}

// Fetching
class TaskStore: ObservableObject {
    @Published var tasks: [CDTask] = []
    private let context: NSManagedObjectContext

    func fetchTasks() {
        let request = CDTask.fetchRequest()
        request.sortDescriptors = [
            NSSortDescriptor(keyPath: \CDTask.createdAt, ascending: false)
        ]

        do {
            tasks = try context.fetch(request)
        } catch {
            print("Fetch failed: \(error)")
        }
    }

    func save() {
        if context.hasChanges {
            try? context.save()
        }
    }
}
```

## MVVM Architecture

### ViewModel

```swift
@MainActor
class TaskListViewModel: ObservableObject {
    @Published var tasks: [TaskItem] = []
    @Published var isLoading = false
    @Published var errorMessage: String?

    private let repository: TaskRepository

    init(repository: TaskRepository = .shared) {
        self.repository = repository
    }

    func loadTasks() async {
        isLoading = true
        errorMessage = nil

        do {
            tasks = try await repository.fetchTasks()
        } catch {
            errorMessage = error.localizedDescription
        }

        isLoading = false
    }

    func addTask(_ title: String) async {
        do {
            let newTask = try await repository.createTask(title: title)
            tasks.insert(newTask, at: 0)
        } catch {
            errorMessage = "Failed to create task"
        }
    }

    func toggleComplete(_ task: TaskItem) async {
        guard let index = tasks.firstIndex(where: { $0.id == task.id }) else { return }
        tasks[index].isCompleted.toggle()

        do {
            try await repository.updateTask(tasks[index])
        } catch {
            tasks[index].isCompleted.toggle() // Revert
            errorMessage = "Failed to update task"
        }
    }
}
```

### View

```swift
struct TaskListView: View {
    @StateObject private var viewModel = TaskListViewModel()
    @State private var showingAddTask = false
    @State private var newTaskTitle = ""

    var body: some View {
        NavigationStack {
            Group {
                if viewModel.isLoading {
                    ProgressView()
                } else if let error = viewModel.errorMessage {
                    ContentUnavailableView(
                        "Error",
                        systemImage: "exclamationmark.triangle",
                        description: Text(error)
                    )
                } else {
                    taskList
                }
            }
            .navigationTitle("Tasks")
            .toolbar {
                Button("Add", systemImage: "plus") {
                    showingAddTask = true
                }
            }
            .sheet(isPresented: $showingAddTask) {
                AddTaskSheet(title: $newTaskTitle) {
                    Task {
                        await viewModel.addTask(newTaskTitle)
                        newTaskTitle = ""
                    }
                }
            }
        }
        .task {
            await viewModel.loadTasks()
        }
    }

    private var taskList: some View {
        List(viewModel.tasks) { task in
            HStack {
                Image(systemName: task.isCompleted ? "checkmark.circle.fill" : "circle")
                    .foregroundColor(task.isCompleted ? .green : .gray)
                    .onTapGesture {
                        Task { await viewModel.toggleComplete(task) }
                    }
                Text(task.title)
                    .strikethrough(task.isCompleted)
            }
        }
    }
}
```

### Repository

```swift
class TaskRepository {
    static let shared = TaskRepository()
    private let network = NetworkService.shared
    private let cache = TaskCache()

    func fetchTasks() async throws -> [TaskItem] {
        // Try network first
        do {
            let tasks: [TaskItem] = try await network.request(
                url: "https://api.example.com/tasks"
            )
            cache.save(tasks)
            return tasks
        } catch {
            // Fall back to cache
            if let cached = cache.load() {
                return cached
            }
            throw error
        }
    }

    func createTask(title: String) async throws -> TaskItem {
        let request = CreateTaskRequest(title: title)
        return try await network.request(
            url: "https://api.example.com/tasks",
            method: .post,
            body: request
        )
    }
}
```

## Dependency Injection

```swift
protocol TaskRepositoryProtocol {
    func fetchTasks() async throws -> [TaskItem]
    func createTask(title: String) async throws -> TaskItem
}

// Production implementation
class TaskRepository: TaskRepositoryProtocol {
    func fetchTasks() async throws -> [TaskItem] {
        // Real API call
    }
}

// Mock for testing and previews
class MockTaskRepository: TaskRepositoryProtocol {
    func fetchTasks() async throws -> [TaskItem] {
        return [
            TaskItem(id: 1, title: "Sample Task", isCompleted: false)
        ]
    }
}

// ViewModel accepts protocol
class TaskListViewModel: ObservableObject {
    private let repository: TaskRepositoryProtocol

    init(repository: TaskRepositoryProtocol = TaskRepository()) {
        self.repository = repository
    }
}

// Preview
#Preview {
    TaskListView()
        .environmentObject(
            TaskListViewModel(repository: MockTaskRepository())
        )
}
```

## Best Practices

### Networking
1. Use async/await for clean async code
2. Handle all error states gracefully
3. Implement request retry logic
4. Cache responses appropriately
5. Use Codable for JSON serialization

### Persistence
1. Use SwiftData for new projects (iOS 17+)
2. Follow the repository pattern
3. Keep models separate from persistence layer
4. Handle migration between schema versions

### Architecture
1. Separate concerns with MVVM
2. Use dependency injection for testability
3. Keep views as thin as possible
4. Use protocols for abstraction
5. Handle loading and error states in every screen

## Conclusion

A solid foundation in networking, persistence, and architecture enables you to build iOS apps that are reliable, testable, and maintainable.

**Key Takeaways:**
1. Use URLSession with async/await for networking
2. SwiftData simplifies modern data persistence
3. MVVM keeps your code organized and testable
4. Repository pattern abstracts data sources
5. Dependency injection enables testing
6. Always handle offline and error scenarios

Happy iOS development!
